window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3cd85247802b0b14"]={"versions": [{"id": "FIG-3cd85247802b0b14", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsschemas (ECUC-Parameterdefinition) für den Ethernet-Treiber (<code>Eth</code>) innerhalb der AUTOSAR Classic Platform. Das Metamodell definiert die Struktur des Moduls auf BSW-Ebene mit seinen Konfigurationscontainern und -parametern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>Eth</code> ist als <code>EcucModuleDef</code> typisiert (Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>). Über eine Kompositionsbeziehung mit der Rolle <code>+container</code> ist der Konfigurationscontainer <code>EthGeneral</code> vom Typ <code>EcucParamConfContainerDef</code> zugeordnet.</p>\n<p class=\"fig-p\"><code>EthGeneral</code> aggregiert über Kompositionsbeziehungen mit der Rolle <code>+parameter</code> folgende Konfigurationsparameter:</p>\n<ul class=\"fig-list\">\n<li><code>EthMaxCtrlsSupported</code> (<code>EcucIntegerParamDef</code>): Wertebereich <code>min = 1</code>, <code>max = 255</code>.</li>\n<li><code>EthDevErrorDetect</code> (<code>EcucBooleanParamDef</code>): Schalter zur Aktivierung der Entwicklungsschnittstellen-Fehlererkennung.</li>\n<li><code>EthVersionInfoApi</code> (<code>EcucBooleanParamDef</code>): Schalter zur Bereitstellung der Versionsinformations-API als Funktion.</li>\n<li><code>EthVersionInfoApiMacro</code> (<code>EcucBooleanParamDef</code>): Schalter zur Bereitstellung der Versionsinformations-API als Makro.</li>\n<li><code>EthIndex</code> (<code>EcucIntegerParamDef</code>): Wertebereich <code>min = 0</code>, <code>max = 255</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Laufzeitinteraktion oder dynamische Sequenzabläufe. Die Definitionen bestimmen die Generierung der BSW-Konfiguration zur Build- bzw. Vorkompilierzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des Konfigurationsschemas für den AUTOSAR-Ethernet-Treiber. Konfigurationstools müssen dieses Schema zur Validierung der Modulkonfiguration implementieren. Die Parameter <code>EthMaxCtrlsSupported</code> und <code>EthIndex</code> erzwingen Integer-Wertebereiche [1..255] bzw. [0..255]. Die booleschen Parameter steuern das bedingte Kompilieren der entsprechenden Treiberschnittstellen (z. B. Det-Aufrufe und Funktions- bzw. Makroimplementierung der Version-Info-API).</p>"}, {"id": "FIG-532c367b9e098426", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des ECU-Konfigurationsschemas (ECUC-Parameterdefinition) für den Ethernet-Treiber (<code>Eth</code>) innerhalb der AUTOSAR Classic Platform. Das Metamodell definiert die Struktur des Moduls auf BSW-Ebene mit seinen Konfigurationscontainern und -parametern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modul <code>Eth</code> ist als <code>EcucModuleDef</code> typisiert (Multiplizität: <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = *</code>). Über eine Kompositionsbeziehung mit der Rolle <code>+container</code> ist der Konfigurationscontainer <code>EthGeneral</code> vom Typ <code>EcucParamConfContainerDef</code> zugeordnet.</p>\n<p class=\"fig-p\"><code>EthGeneral</code> aggregiert über Kompositionsbeziehungen mit der Rolle <code>+parameter</code> folgende Konfigurationsparameter:</p>\n<ul class=\"fig-list\">\n<li><code>EthMaxCtrlsSupported</code> (<code>EcucIntegerParamDef</code>): Wertebereich <code>min = 1</code>, <code>max = 255</code>.</li>\n<li><code>EthDevErrorDetect</code> (<code>EcucBooleanParamDef</code>): Schalter zur Aktivierung der Entwicklungsschnittstellen-Fehlererkennung.</li>\n<li><code>EthVersionInfoApi</code> (<code>EcucBooleanParamDef</code>): Schalter zur Bereitstellung der Versionsinformations-API.</li>\n<li><code>EthIndex</code> (<code>EcucIntegerParamDef</code>): Wertebereich <code>min = 0</code>, <code>max = 255</code>.</li>\n<li><code>EthUpdatePhysAddrFilter</code> (<code>EcucBooleanParamDef</code>): Boolescher Parameter mit Attribut <code>defaultValue = false</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne Laufzeitinteraktion oder dynamische Sequenzabläufe. Die Definitionen bestimmen die Generierung der BSW-Konfiguration zur Build- bzw. Vorkompilierzeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des Konfigurationsschemas für den AUTOSAR-Ethernet-Treiber. Konfigurationstools müssen dieses Schema zur Validierung der Modulkonfiguration implementieren. Die Parameter <code>EthMaxCtrlsSupported</code> und <code>EthIndex</code> erzwingen Integer-Wertebereiche [1..255] bzw. [0..255]. <code>EthUpdatePhysAddrFilter</code> ist mit dem Standardwert <code>false</code> initialisiert. Die booleschen Parameter steuern das bedingte Kompilieren und Freischalten der entsprechenden Treiberschnittstellen und Filterfunktionalitäten.</p>"}], "trans": [{"from": "FIG-3cd85247802b0b14", "to": "FIG-532c367b9e098426", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Parameter <code>EthVersionInfoApiMacro : EcucBooleanParamDef</code> entfernt</li>\n<li>Parameter <code>EthUpdatePhysAddrFilter : EcucBooleanParamDef</code> mit Attribut <code>defaultValue = false</code> hinzugefügt</li>\n</ul>"}]};
